function sceneFamilyFor(puzzle) {
  if (puzzle.world === 'computer') return 'computer';
  if (puzzle.world === 'tv') return 'device';
  if (puzzle.world === 'phone') return 'phone';
  return puzzle.environment || puzzle.family || puzzle.world || 'computer';
}

